/* Alert container */
.alert {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 39px;
  padding: 12px 16px;
  border-radius: 4px;
  font-family: Inter, -apple-system, Roboto, Helvetica, sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: normal;
  letter-spacing: -0.28px;
  box-sizing: border-box;
}

/* Variant-specific backgrounds and text colors */
.alert-default {
  background: #bae6fd; /* Sky-200 */
  color: #0284c7; /* Sky-600 */
}

.alert-info {
  background: #bfdbfe; /* Blue-200 */
  color: #2563eb; /* Blue-600 */
}

.alert-success {
  background: #bbf7d0; /* Green-200 */
  color: #16a34a; /* Green-600 */
}

.alert-warning {
  background: #fef08a; /* Yellow-200 */
  color: #ca8a04; /* Yellow-600 */
}

.alert-destructive {
  background: #fecaca; /* Red-200 */
  color: #dc2626; /* Red-600 */
}

/* Icon */
.alert-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
}

/* Content text */
.alert-content {
  flex: 1;
  text-align: left;
}

/* Close button */
.alert-close {
  flex-shrink: 0;
  width: 8px;
  height: 8px;
  padding: 0;
  border: none;
  background: transparent;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.alert-close:hover {
  opacity: 0.8;
}

.alert-close:focus {
  outline: none;
}

.alert-close:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
  border-radius: 2px;
}

