  color: #1d4ed8;
  box-shadow:
    0 0 0 3px white,
    0 0 0 4px #2e1065;
}

/* Destructive variant */
.btn-destructive {
  background: #dc2626;
  color: white;
}

.btn-destructive:hover:not(:disabled),
.btn-state-hover.btn-destructive {
  opacity: 0.9;
}

.btn-destructive:active:not(:disabled),
.btn-state-active.btn-destructive {
  box-shadow: 0 2px 4px 0 rgba(0, 0, 0, 0.12) inset;
}

.btn-destructive:active:not(:disabled) .button-label,
.btn-state-active.btn-destructive .button-label {
  text-decoration: underline;
}

.btn-destructive:focus:not(:disabled),
.btn-state-focus.btn-destructive {
  background: #b91c1c;
  box-shadow:
    0 0 0 3px white,
    0 0 0 4px #2e1065;
}

/* Disabled state */
.btn:disabled,
.btn-state-disabled {
  opacity: 0.4;
  cursor: not-allowed;
  pointer-events: none;
}

/* Icon styling */
.button-icon {
  flex-shrink: 0;
}

.button-icon-left {
  margin-right: -2px;
}

.button-icon-right {
  margin-left: -2px;
}

.btn-shape-icon .button-icon {
  margin: 0;
}

/* Label styling */
.button-label {
  display: inline-block;
}

/* Focus visible for accessibility */
.btn:focus-visible {
  box-shadow:
    0 0 0 3px white,
    0 0 0 4px #2e1065;
}

/* ===========================
   Icon-only Circular Button States
   =========================== */

/* Default state - already defined above */
.btn-shape-icon-only {
  position: relative;
}

/* Hover state */
.btn-shape-icon-only:hover:not(:disabled),
.btn-shape-icon-only.btn-state-hover {
  opacity: 0.9;
}

/* Active state */
.btn-shape-icon-only:active:not(:disabled),
.btn-shape-icon-only.btn-state-active {
  opacity: 1;
}

/* Focus state - darker border, darker icon, purple ring */
.btn-shape-icon-only:focus:not(:disabled),
.btn-shape-icon-only.btn-state-focus {
  border-color: #64748b;
  color: #6b21a8;
  outline: none;
  box-shadow: 0 0 0 1px #581c87;
}

/* Disabled state */
.btn-shape-icon-only:disabled,
.btn-shape-icon-only.btn-state-disabled {
  opacity: 0.4;
  cursor: not-allowed;
  pointer-events: none;
}

/* Icon-only button icon wrapper */
.button-icon-only {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
}

/* Icon sizing for icon-only buttons */
.btn-shape-icon-only.btn-sm .button-icon-only {
  width: 17px;
  height: 17px;
}

.btn-shape-icon-only.btn-md .button-icon-only {
  width: 21px;
  height: 21px;
}

.btn-shape-icon-only.btn-lg .button-icon-only {
  width: 26px;
  height: 26px;
}

/* Ensure SVG icons render properly in icon-only buttons */
.button-icon-only svg {
  display: block;
  width: 100%;
  height: 100%;
}

/* Card Container */
.card {
  display: flex;
  flex-direction: column;
  width: 393px;
  padding: 24px 20px;
  gap: 16px;
  border-radius: 8px;
  background: #fff;
  box-sizing: border-box;
  transition:
    opacity 0.2s ease,
    box-shadow 0.2s ease;
}

/* Variant: Default */
.card-default {
  border: 1px solid #e4e4e7;
}

/* Variant: Elevated */
.card-elevated {
  border: 1px solid #e4e4e7;
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.08);
}

/* Variant: Outlined */
.card-outlined {
  border: 1px solid #e4e4e7;
  background: #fff;
}

/* Hover State */
.card-hover {
  opacity: 0.9;
}

/* Header Row */
.card-header-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

/* Card Header */
.card-header {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #434c57;
  font-family:
    Inter,
    -apple-system,
    Roboto,
    Helvetica,
    sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: normal;
}

/* Info Icon */
.card-info-icon {
  width: 17px;
  height: 17px;
  flex-shrink: 0;
}

/* Action Icon (phone, etc.) */
.card-action-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

/* Value */
.card-value {
  color: #2d2929;
  font-family:
    Inter,
    -apple-system,
    Roboto,
    Helvetica,
    sans-serif;
  font-size: 32px;
  font-weight: 800;
  line-height: 1.2;
}

/* Helper Row */
.card-helper-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

/* Helper */
.card-helper {
  color: #16a34a; /* Green for positive changes */
  font-family:
    Inter,
    -apple-system,
    Roboto,
    Helvetica,
    sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: normal;
  flex-shrink: 0;
}

/* Helper Description */
.card-helper-description {
  color: #707688;
  font-family:
    Inter,
    -apple-system,
    Roboto,
    Helvetica,
    sans-serif;
  font-size: 13px;
  font-weight: 400;
  line-height: normal;
}

/* Helper color variants */
.card-helper[data-type='positive'] {
  color: #16a34a; /* Green */
}

.card-helper[data-type='negative'] {
  color: #dc2626; /* Red */
}

.card-helper[data-type='neutral'] {
  color: #707688; /* Gray */
}

/* ===========================
   Content Variant: metric
   =========================== */
.card-content-metric {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 16px 89px;
  min-height: 87px;
  background: #fef2f2;
  border: 1px solid #fecaca;
}

.card-metric-title {
  display: flex;
  justify-content: center;
  color: rgba(71, 85, 105, 1);
  font-family:
    Inter,
    -apple-system,
    Roboto,
    Helvetica,
    sans-serif;
  font-size: 12px;
  font-weight: 500;
  line-height: normal;
  text-align: center;
}

.card-metric-value {
  display: flex;
  justify-content: center;
  color: #dc2626;
  font-family:
    Inter,
    -apple-system,
    Roboto,
    Helvetica,
    sans-serif;
  font-size: 24px;
  font-weight: 700;
  line-height: normal;
  text-align: center;
}

/* ===========================
   Content Variant: infoDate
   =========================== */
.card-content-infoDate {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 17px 8px;
  min-height: 84px;
  width: fit-content;
  max-width: 101px;
  background: #eff6ff;
  border: none;
}

.card-info-label {
  display: flex;
  justify-content: center;
  color: rgba(71, 85, 105, 1);
  font-family:
    Inter,
    -apple-system,
    Roboto,
    Helvetica,
    sans-serif;
  font-size: 12px;
  font-weight: 500;
  line-height: normal;
  text-align: center;
}

.card-info-text {
  display: flex;
  justify-content: center;
  color: rgba(71, 85, 105, 1);
  font-family:
    Inter,
    -apple-system,
    Roboto,
    Helvetica,
    sans-serif;
  font-size: 14px;
  font-weight: 700;
  line-height: normal;
  text-align: center;
}

/* ===========================
   Content Variant: infoCurrency
   =========================== */
.card-content-infoCurrency {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  gap: 16px;
  padding: 16px;
  min-height: 90px;
  width: fit-content;
  max-width: 273px;
  background: #dbeafe;
  border: none;
}

.card-currency-label {
  display: flex;
  color: rgba(51, 65, 85, 1);
  font-family:
    Inter,
    -apple-system,
    Roboto,
    Helvetica,
    sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: normal;
}

.card-currency-content {
  display: flex;
  align-items: center;
  gap: 8px;
}

.card-currency-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 21px;
  height: 21px;
}

.card-currency-icon svg {
  display: block;
  width: 100%;
  height: 100%;
}

.card-currency-text {
  display: flex;
  color: #2563eb;
  font-family:
    Inter,
    -apple-system,
    Roboto,
    Helvetica,
    sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: normal;
}

/* ===========================
   Content Variant: placeholder
   =========================== */
.card-content-placeholder {
  width: 277px;
  min-height: 225px;
  border: 1px solid rgba(226, 232, 240, 1);
  background: transparent;
  border-radius: 8px;
  padding: 0;
}

/* Responsive behavior */
@media (max-width: 768px) {
  .card {
    width: 100%;
    max-width: 393px;
  }

  .card-content-metric {
    padding: 16px 40px;
  }

  .card-content-infoCurrency {
    max-width: 100%;
    width: 100%;
  }

  .card-content-placeholder {
    width: 100%;
    max-width: 277px;
  }
}

@media (max-width: 480px) {
  .card {
    padding: 20px 16px;
    gap: 14px;
  }

  .card-header {
    font-size: 13px;
  }

  .card-value {
    font-size: 28px;
  }

  .card-helper {
    font-size: 13px;
  }

  .card-helper-description {
    font-size: 12px;
  }

  .card-content-metric {
    padding: 16px 20px;
  }

  .card-metric-title {
    font-size: 11px;
  }

  .card-metric-value {
    font-size: 20px;
  }

  .card-currency-label {
    font-size: 13px;
  }

  .card-currency-text {
    font-size: 18px;
  }
}

