/* Base input wrapper styles */
.input-wrapper {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  border-radius: 6px;
  border: 1px solid;
  box-sizing: border-box;
  position: relative;
  transition: all 0.2s ease;
}

/* Input field base styles */
.input-field {
  flex: 1;
  border: none;
  outline: none;
  background: transparent;
  font-family: Inter, -apple-system, Roboto, Helvetica, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 24px;
  letter-spacing: 0.05px;
  color: #1E293B;
  box-sizing: border-box;
}

.input-field::placeholder {
  color: #64748B;
}

/* Icon styling */
.input-icon {
  flex-shrink: 0;
}

/* Size variants */
.input-sm {
  height: 32px;
  padding: 4px 12px;
}

.input-md {
  height: 40px;
  padding: 4px 12px;
}

.input-lg {
  height: 48px;
  padding: 4px 12px;
}

/* State variants - Default */
.input-state-default {
  border-color: #CBD5E1;
  background: transparent;
}

.input-state-default:hover,
.input-state-default.input-state-hover {
  opacity: 0.9;
}

.input-state-default .input-field:focus {
  outline: none;
}

/* State variants - Hover */
.input-state-hover {
  border-color: #CBD5E1;
  background: transparent;
  opacity: 0.9;
}

/* State variants - Focus */
.input-state-focus,
.input-wrapper:has(.input-field:focus) {
  border-color: #64748B;
  background: transparent;
  box-shadow: 0 0 0 3px white, 0 0 0 4px #7C3AED;
}

.input-state-focus .input-field,
.input-wrapper:has(.input-field:focus) .input-field {
  color: #1E293B;
}

/* Focus state for error (destructive) - keep red border, purple ring only */
.input-state-error.input-state-focus,
.input-state-error:has(.input-field:focus) {
  border-color: #DC2626;
  background: transparent;
  box-shadow: 0 0 0 3px white, 0 0 0 4px #7C3AED;
}

/* State variants - Disabled */
.input-state-disabled {
  border-color: #CBD5E1;
  background: transparent;
  opacity: 0.4;
  cursor: not-allowed;
  pointer-events: none;
}

.input-state-disabled .input-field {
  cursor: not-allowed;
}

/* State variants - Error */
.input-state-error {
  border-color: #DC2626;
  background: transparent;
}

.input-state-error .input-field {
  color: #DC2626;
}

.input-state-error .input-field::placeholder {
  color: #DC2626;
}

/* Remove browser default focus styles */
.input-field:focus {
  outline: none;
}

/* Ensure consistent box-sizing */
* {
  box-sizing: border-box;
}

