/* ===========================
   Circular Progress
   =========================== */

.circular-progress {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.circular-progress-sm {
  width: 40px;
  height: 40px;
}

.circular-progress-md {
  width: 64px;
  height: 64px;
}

.circular-progress-lg {
  width: 124px;
  height: 124px;
}

/* SVG circles */
.progress-track {
  stroke: #e2e8f0; /* neutral-200 */
}

.progress-fill {
  stroke: #2563eb; /* Blue-600 */
  stroke-linecap: round;
  transition: stroke-dashoffset 0.3s ease;
}

/* Circular indeterminate animation */
@keyframes circular-rotate {
  0% {
    transform: rotate(-90deg);
  }
  100% {
    transform: rotate(270deg);
  }
}

@keyframes circular-dash {
  0% {
    stroke-dashoffset: 0;
  }
  50% {
    stroke-dashoffset: -80;
  }
  100% {
    stroke-dashoffset: -160;
  }
}

.progress-indeterminate {
  animation: circular-rotate 2s linear infinite, circular-dash 1.5s ease-in-out infinite;
}

/* Center content for circular determinate */
.circular-content {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

/* Percentage text */
.circular-percentage {
  font-family: Inter, -apple-system, Roboto, Helvetica, sans-serif;
  font-weight: 700;
  color: #2563eb; /* Blue-600 */
  line-height: 1;
}

.circular-percentage-sm {
  font-size: 12px;
}

.circular-percentage-md {
  font-size: 20px;
}

.circular-percentage-lg {
  font-size: 25px;
}

/* Label text (only for lg size) */
.circular-label {
  font-family: Inter, -apple-system, Roboto, Helvetica, sans-serif;
  font-size: 9px;
  font-weight: 500;
  color: #94a3b8; /* neutral-400 */
  margin-top: 4px;
  white-space: nowrap;
}

/* ===========================
   Linear Progress
   =========================== */

.linear-progress-container {
  width: 100%;
  max-width: 286px;
}

/* Label for linear determinate */
.linear-label {
  font-family: Inter, -apple-system, Roboto, Helvetica, sans-serif;
  font-size: 15px;
  font-weight: 600;
  color: #1e40af; /* Blue-800 */
  margin-bottom: 8px;
  display: flex;
  justify-content: space-between;
  line-height: 1;
}

/* Linear progress bar container */
.linear-progress {
  position: relative;
  width: 100%;
  height: 8px;
  border-radius: 9999px;
  overflow: hidden;
}

/* Track (background) */
.linear-track {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: #cbd5e1; /* neutral-300 */
  border-radius: 9999px;
}

/* Fill (progress) */
.linear-fill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  background: #2563eb; /* Blue-600 */
  border-radius: 9999px;
  transition: width 0.3s ease;
}

/* Linear indeterminate animation */
@keyframes linear-indeterminate {
  0% {
    left: -35%;
    right: 100%;
  }
  60% {
    left: 100%;
    right: -90%;
  }
  100% {
    left: 100%;
    right: -90%;
  }
}

@keyframes linear-indeterminate-short {
  0% {
    left: -200%;
    right: 100%;
  }
  60% {
    left: 107%;
    right: -8%;
  }
  100% {
    left: 107%;
    right: -8%;
  }
}

.linear-indeterminate {
  width: auto !important;
  animation: linear-indeterminate 2.1s cubic-bezier(0.65, 0.815, 0.735, 0.395) infinite;
}

.linear-indeterminate::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  background: inherit;
  animation: linear-indeterminate-short 2.1s cubic-bezier(0.165, 0.84, 0.44, 1) infinite;
  animation-delay: 1.15s;
}

/* Responsive behavior */
@media (max-width: 768px) {
  .linear-progress-container {
    max-width: 100%;
  }

  .linear-label {
    font-size: 13px;
  }
}

