.radio-focus-ring {
  position: absolute;
  top: 0;
  left: 0;
  pointer-events: none;
}

.radio-outer {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.radio-inner {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

/* State-specific styles */

