/* Base textarea wrapper styles */
.textarea-wrapper {
  display: inline-flex;
  align-items: flex-start;
  gap: 12px;
  border-radius: 6px;
  border: 1px solid;
  box-sizing: border-box;
  padding: 8px 12px;
  transition: all 0.2s ease;
  width: 100%;
  max-width: 203px;
  min-height: 80px;
}

/* Textarea field base styles */
.textarea-field {
  flex: 1;
  width: 100%;
  border: none;
  outline: none;
  background: transparent;
  font-family: Inter, -apple-system, Roboto, Helvetica, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 24px;
  letter-spacing: 0.05px;
  color: #64748B;
  box-sizing: border-box;
  resize: none;
  padding: 0;
  margin: 0;
}

.textarea-field::placeholder {
  color: #64748B;
}

/* State variants - Default */
.textarea-state-default {
  border-color: #CBD5E1;
  background: transparent;
}

.textarea-state-default:hover,
.textarea-state-default.textarea-state-hover {
  opacity: 0.9;
}

.textarea-state-default .textarea-field:focus {
  outline: none;
}

/* State variants - Hover */
.textarea-state-hover {
  border-color: #CBD5E1;
  background: transparent;
  opacity: 0.9;
}

/* State variants - Focus */
.textarea-state-focus,
.textarea-wrapper:has(.textarea-field:focus) {
  border-color: #CBD5E1;
  background: transparent;
  box-shadow: 0 0 0 3px white, 0 0 0 4px #7C3AED;
}

.textarea-state-focus .textarea-field,
.textarea-wrapper:has(.textarea-field:focus) .textarea-field {
  color: #64748B;
}

/* State variants - Disabled */
.textarea-state-disabled {
  border-color: #CBD5E1;
  background: transparent;
  opacity: 0.4;
  cursor: not-allowed;
  pointer-events: none;
}

.textarea-state-disabled .textarea-field {
  cursor: not-allowed;
}

/* State variants - Error */
.textarea-state-error {
  border-color: #DC2626;
  background: transparent;
}

.textarea-state-error .textarea-field {
  color: #DC2626;
}

.textarea-state-error .textarea-field::placeholder {
  color: #DC2626;
}

/* Remove browser default focus styles */
.textarea-field:focus {
  outline: none;
}

/* Ensure consistent box-sizing */
* {
  box-sizing: border-box;
}

/* Scrollbar styling (optional, for better UX) */
.textarea-field::-webkit-scrollbar {
  width: 8px;
}

.textarea-field::-webkit-scrollbar-track {
  background: transparent;
}

.textarea-field::-webkit-scrollbar-thumb {
  background: #CBD5E1;
  border-radius: 4px;
}

.textarea-field::-webkit-scrollbar-thumb:hover {
  background: #94A3B8;
}

/* Toast container */
.toast {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 39px;
  padding: 12px 16px;
  padding-left: 25px; /* 16px + 9px for left accent */
  border-radius: 4px;
  border: 1px solid #e2e8f0; /* neutral-200 */
  background: #fff;
  font-family: Inter, -apple-system, Roboto, Helvetica, sans-serif;
  font-size: 14px;
  font-weight: 500;
  line-height: normal;
  letter-spacing: -0.28px;
  box-sizing: border-box;
}

/* Left accent border */
.toast-accent {
  position: absolute;
  left: 0;
  top: 0;
  width: 9px;
  height: 100%;
  border-radius: 4px 0 0 4px;
}

/* Variant-specific accent colors and text colors */
.toast-default {
  color: #0284c7; /* Sky-600 */
}

.toast-accent-default {
  background: #bae6fd; /* Sky-200 */
}

.toast-info {
  color: #2563eb; /* Blue-600 */
}

.toast-accent-info {
  background: #bfdbfe; /* Blue-200 */
}

.toast-success {
  color: #16a34a; /* Green-600 */
}

.toast-accent-success {
  background: #bbf7d0; /* Green-200 */
}

.toast-warning {
  color: #ca8a04; /* Yellow-600 */
}

.toast-accent-warning {
  background: #fef08a; /* Yellow-200 */
}

.toast-destructive {
  color: #dc2626; /* Red-600 */
}

.toast-accent-destructive {
  background: #fecaca; /* Red-200 */
}

/* Icon */
.toast-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
}

/* Content text */
.toast-content {
  flex: 0 1 auto;
  text-align: left;
  white-space: nowrap;
}

/* Close button */
.toast-close {
  flex-shrink: 0;
  width: 8px;
  height: 8px;
  padding: 0;
  border: none;
  background: transparent;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.toast-close:hover {
  opacity: 0.8;
}

.toast-close:focus {
  outline: none;
}

.toast-close:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
  border-radius: 2px;
}
